'use strict';
/*
 * Local source-built Sputnik fallback with a single frozen inherited-state bundle.
 * The old proposal is created once; each branch imports the exact same code,
 * raw state, contract balance, proposer identity/balance and recipient balance.
 * The seeded bad candidate is generated by build-seeded-bad-candidate.cjs.
 */
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const { Worker, KeyPair, parseNEAR, hashContract } = require('near-workspaces');

const HERE = __dirname;
const OUT = path.join(HERE, 'out');
const BASE = path.resolve(process.env.BASE_WASM || path.join(HERE, '..', 'sputnik-226', 'verified-case', 'base.wasm'));
const CANDIDATE = path.resolve(process.env.CANDIDATE_WASM || path.join(HERE, '..', 'sputnik-226', 'verified-case', 'candidate.wasm'));
const BAD = path.resolve(process.env.BAD_WASM || path.join(HERE, 'artifacts', 'candidate-seeded-bad.wasm'));
const GAS = 300_000_000_000_000n;
const BOND = parseNEAR('1');
const DAO_ID = 'dao.test.near';
const ACTOR_ID = 'proposer.test.near';
const RECIPIENT_ID = 'recipient.test.near';
const MAX_WAIT_MS = 60_000;
const ACTOR_KEY = KeyPair.fromRandom('ed25519');
const sha256 = (b) => crypto.createHash('sha256').update(b).digest('hex');
const json = (v) => JSON.stringify(v, (_, x) => typeof x === 'bigint' ? x.toString() : x, 2);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const sorted = (items) => items.map(({ key, value }) => ({ key, value })).sort((a, b) => a.key.localeCompare(b.key));
const stateHash = (items) => sha256(JSON.stringify(sorted(items)));
const b64 = (b) => Buffer.from(b).toString('base64');

function assertLocal(worker) {
  const rpc = worker.config?.rpcAddr || worker.provider?.connection?.url;
  const host = new URL(rpc).hostname;
  if (!['127.0.0.1', 'localhost', '::1'].includes(host)) throw new Error(`refusing non-local execution RPC: ${rpc}`);
  return rpc;
}
async function readState(worker, id) {
  return sorted((await worker.provider.viewStateRaw(id, '', { finality: 'final' })).map(({ key, value }) => ({ key, value })));
}
async function viewJson(worker, id, method, args = {}) {
  const r = await worker.provider.viewCall(id, method, args, { finality: 'final' });
  if (!r || !Array.isArray(r.result)) throw new Error(`${method} returned no result`);
  return JSON.parse(Buffer.from(r.result).toString('utf8'));
}
async function viewAmount(worker, id) {
  return (await worker.provider.viewAccount(id, { finality: 'final' })).amount;
}
async function finalStatus(worker, tx, sender) {
  const hash = tx?.transactionReceipt?.hash;
  if (!hash) throw new Error('transaction has no hash');
  const started = Date.now();
  let last;
  while (Date.now() - started < MAX_WAIT_MS) {
    try {
      const status = await worker.provider.sendJsonRpc('tx', { tx_hash: hash, sender_account_id: sender });
      if (status?.final_execution_status === 'FINAL') return { status, hash };
      last = status;
    } catch (e) { last = { error: e.message }; }
    await sleep(500);
  }
  throw new Error(`tx ${hash} did not reach FINAL: ${JSON.stringify(last)}`);
}
function txSummary(tx, final) {
  const txOutcome = final?.status?.transaction_outcome;
  const outcome = txOutcome?.outcome;
  const receipts = (final?.status?.receipts_outcome || []).map((r) => ({
    id: r.id,
    blockHash: r.block_hash ?? null,
    receiptIds: r.outcome?.receipt_ids ?? [],
    executorId: r.outcome?.executor_id ?? null,
    status: r.outcome?.status ?? null,
    gasBurntUnits: r.outcome?.gas_burnt?.toString() ?? null,
    tokensBurntYocto: r.outcome?.tokens_burnt?.toString() ?? null,
    logs: r.outcome?.logs ?? [],
  }));
  const txTokens = BigInt(outcome?.tokens_burnt ?? 0);
  const receiptTokens = receipts.reduce((n, r) => n + BigInt(r.tokensBurntYocto ?? 0), 0n);
  return {
    transactionHash: final?.hash ?? tx?.transactionReceipt?.hash ?? null,
    succeeded: tx?.succeeded === true,
    failed: tx?.failed === true,
    failure: tx?.Failure ?? null,
    finalExecutionStatus: final?.status?.final_execution_status ?? null,
    transaction: {
      signerId: final?.status?.transaction?.signer_id ?? null,
      receiverId: final?.status?.transaction?.receiver_id ?? null,
      actions: final?.status?.transaction?.actions ?? [],
      transactionOutcomeBlockHash: txOutcome?.block_hash ?? null,
    },
    receiptIds: outcome?.receipt_ids ?? [],
    gasBurntUnits: outcome?.gas_burnt?.toString() ?? null,
    transactionOutcomeTokensBurntYocto: txTokens.toString(),
    receiptTokensBurntYocto: receiptTokens.toString(),
    totalTokensBurntYocto: (txTokens + receiptTokens).toString(),
    transactionOutcomeStatus: outcome?.status ?? null,
    receipts,
    receiptFailures: tx?.receiptFailures ?? [],
  };
}
async function waitAccount(account, label) {
  for (let i = 0; i < 80; i++) {
    await sleep(250);
    if (await account.exists().catch(() => false)) return;
  }
  throw new Error(`${label} did not appear`);
}

async function initWorker() {
  let last;
  for (let i = 0; i < 3; i++) {
    try { return await Worker.init({ network: 'sandbox' }); }
    catch (e) { last = e; await sleep(2000); }
  }
  throw last;
}
async function createTemplate() {
  console.error('stage: freeze template');
  const worker = await initWorker();
  try {
    assertLocal(worker);
    await worker.provider.status();
    await worker.rootAccount.accountView();
    await sleep(500);
    const root = worker.rootAccount;
    const dao = await root.createSubAccount('dao', { initialBalance: parseNEAR('100') });
    const proposer = await root.createSubAccount('proposer', { initialBalance: parseNEAR('100'), keyPair: ACTOR_KEY });
    const recipient = await root.createSubAccount('recipient', { initialBalance: parseNEAR('10') });
    const base = fs.readFileSync(BASE);
    const deploy = await dao.deploy(base);
    const deployFinal = await finalStatus(worker, deploy, root.accountId);
    const init = await root.callRaw(dao, 'new', { config: { name: 'pilot', purpose: 'local frozen inherited-state three-branch fixture', metadata: '' }, policy: [proposer.accountId] }, { gas: GAS });
    const initFinal = await finalStatus(worker, init, root.accountId);
    const transferKind = { Transfer: { token_id: '', receiver_id: recipient.accountId, amount: BOND.toString(), msg: null } };
    const add = await proposer.callRaw(dao, 'add_proposal', { proposal: { description: 'pre-upgrade transfer proposal', kind: transferKind } }, { gas: GAS, attachedDeposit: BOND });
    const addFinal = await finalStatus(worker, add, proposer.accountId);
    const proposalId = add.parseResult();
    const state = await readState(worker, dao.accountId);
    const code = await dao.viewCode();
    const contractView = await dao.accountView();
    const actorView = await proposer.accountView();
    const recipientAmount = await viewAmount(worker, recipient.accountId);
    const policy = await viewJson(worker, dao.accountId, 'get_policy');
    const proposal = await viewJson(worker, dao.accountId, 'get_proposal', { id: proposalId });
    const block = await worker.provider.sendJsonRpc('block', { finality: 'final' });
    const bundle = {
      schema: 'near-rehearsal/local-frozen-sputnik-bundle/v1',
      createdAt: new Date().toISOString(),
      source: 'local source-built Sputnik configured-factory fixture',
      network: 'sandbox',
      identities: { contract: DAO_ID, proposer: ACTOR_ID, recipient: RECIPIENT_ID, factory: root.accountId, proposerPublicKey: ACTOR_KEY.getPublicKey().toString() },
      artifacts: { baseSha256: sha256(base), baseHash: hashContract(base), candidateSha256: sha256(fs.readFileSync(CANDIDATE)), candidateHash: hashContract(fs.readFileSync(CANDIDATE)), seededBadSha256: sha256(fs.readFileSync(BAD)), seededBadHash: hashContract(fs.readFileSync(BAD)) },
      contractAccount: { amount: contractView.amount, storage_usage: contractView.storage_usage, code_hash: contractView.code_hash, locked: contractView.locked },
      actorAccount: { amount: actorView.amount, storage_usage: actorView.storage_usage, code_hash: actorView.code_hash, locked: actorView.locked },
      recipientAmount,
      code: b64(code),
      state,
      stateHash: stateHash(state),
      codeHash: hashContract(code),
      policy,
      proposal,
      proposalId,
      transferKind,
      context: {
        frozenAtLocalBlock: { height: block.header.height, hash: block.header.hash, timestamp: String(block.header.timestamp_nanosec ?? block.header.timestamp) },
        note: 'Proposal submission timestamp is frozen in raw state. Fresh branch local block timestamps differ; this is recorded, not treated as the inherited timestamp.',
      },
      templateTransactions: { deploy: txSummary(deploy, deployFinal), init: txSummary(init, initFinal), add: txSummary(add, addFinal) },
    };
    fs.writeFileSync(path.join(OUT, 'local-frozen-bundle.json'), json(bundle) + '\n');
    console.error('frozen', JSON.stringify({ stateHash: bundle.stateHash, codeHash: bundle.codeHash, contractBalance: bundle.contractAccount.amount, actorBalance: bundle.actorAccount.amount, proposal: { id: proposalId, status: proposal.status } }));
    return bundle;
  } finally { await worker.tearDown(); }
}

async function importBundle(bundle) {
  console.error('stage: import frozen bundle');
  const worker = await initWorker();
  assertLocal(worker);
  await worker.provider.status();
  await worker.rootAccount.accountView();
  await sleep(500);
  const root = worker.rootAccount;
  if (!(await root.getAccount(DAO_ID).exists().catch(() => false))) {
    await root.createSubAccount('dao', { initialBalance: parseNEAR('1') });
  }
  const dao = root.getAccount(DAO_ID);
  const rb = dao.recordBuilder();
  rb.account(bundle.contractAccount);
  rb.contract(Buffer.from(bundle.code, 'base64'));
  for (const item of bundle.state) rb.data(item.key, item.value);
  await dao.patchStateRecords(rb);
  await sleep(750);
  if (!(await dao.exists().catch(() => false))) await dao.patchStateRecords(rb);
  await waitAccount(dao, 'contract');
  if (!(await root.getAccount(ACTOR_ID).exists().catch(() => false))) {
    await root.createSubAccount('proposer', { initialBalance: parseNEAR('1'), keyPair: ACTOR_KEY });
  }
  const proposer = root.getAccount(ACTOR_ID);
  const arb = proposer.recordBuilder();
  arb.account(bundle.actorAccount);
  arb.accessKey(ACTOR_KEY.getPublicKey());
  await proposer.patchStateRecords(arb);
  await sleep(750);
  if (!(await proposer.exists().catch(() => false))) await proposer.patchStateRecords(arb);
  await waitAccount(proposer, 'proposer');
  await proposer.setKey(ACTOR_KEY);
  let accessKeyView;
  for (let i = 0; i < 40; i++) {
    try { accessKeyView = await worker.provider.viewAccessKey(proposer.accountId, ACTOR_KEY.getPublicKey().toString(), { finality: 'final' }); break; }
    catch (e) { if (i === 39) throw new Error(`proposer access key missing: ${e.message}`); await sleep(250); }
  }
  const recipient = await root.createSubAccount('recipient', { initialBalance: bundle.recipientAmount });
  let recipientBalance;
  for (let i = 0; i < 40; i++) {
    try { recipientBalance = await viewAmount(worker, recipient.accountId); break; }
    catch (e) { if (i === 39) throw new Error(`recipient amount unavailable: ${e.message}`); await sleep(250); }
  }
  const imported = {
    codeHash: hashContract(await dao.viewCode()),
    stateHash: stateHash(await readState(worker, dao.accountId)),
    contractBalance: (await dao.accountView()).amount,
    actorBalance: (await proposer.accountView()).amount,
    recipientBalance,
    policy: await viewJson(worker, dao.accountId, 'get_policy'),
    proposal: await viewJson(worker, dao.accountId, 'get_proposal', { id: bundle.proposalId }),
    accessKeyView,
  };
  const localBlock = await worker.provider.sendJsonRpc('block', { finality: 'final' });
  const facts = {
    codeHash: imported.codeHash, stateHash: imported.stateHash,
    contractBalance: imported.contractBalance, actorBalance: imported.actorBalance,
    recipientBalance: imported.recipientBalance,
    policy: imported.policy, proposal: imported.proposal,
    identities: { contract: DAO_ID, proposer: ACTOR_ID, recipient: RECIPIENT_ID, factory: root.accountId },
  };
  const factsHash = sha256(JSON.stringify(facts));
  const expected = {
    codeHash: bundle.codeHash, stateHash: bundle.stateHash,
    contractBalance: bundle.contractAccount.amount, actorBalance: bundle.actorAccount.amount,
    recipientBalance: bundle.recipientAmount, policy: bundle.policy, proposal: bundle.proposal,
    identities: bundle.identities,
  };
  const matches = imported.codeHash === expected.codeHash && imported.stateHash === expected.stateHash && imported.contractBalance === expected.contractBalance && imported.actorBalance === expected.actorBalance && imported.recipientBalance === expected.recipientBalance && JSON.stringify(imported.policy) === JSON.stringify(expected.policy) && JSON.stringify(imported.proposal) === JSON.stringify(expected.proposal) && facts.identities.contract === expected.identities.contract && facts.identities.proposer === expected.identities.proposer && facts.identities.recipient === expected.identities.recipient;
  console.error('imported', JSON.stringify({ matches, stateHash: imported.stateHash, contractBalance: imported.contractBalance, actorBalance: imported.actorBalance, factsHash }));
  if (!matches) throw new Error(`frozen bundle import mismatch: ${JSON.stringify({ imported, expected })}`);
  return { worker, root, dao, proposer, recipient, bundle, imported, factsHash, localBlock: { height: localBlock.header.height, hash: localBlock.header.hash, timestamp: String(localBlock.header.timestamp_nanosec ?? localBlock.header.timestamp) } };
}
async function close(branch) { try { await branch.worker.tearDown(); } catch {} }
async function snapshot(branch) {
  return {
    codeHash: hashContract(await branch.dao.viewCode()),
    stateHash: stateHash(await readState(branch.worker, DAO_ID)),
    proposal: await viewJson(branch.worker, DAO_ID, 'get_proposal', { id: branch.bundle.proposalId }),
    recipientBalance: await viewAmount(branch.worker, RECIPIENT_ID),
  };
}
async function approve(branch) {
  const tx = await branch.proposer.callRaw(branch.dao, 'act_proposal', { id: branch.bundle.proposalId, action: 'VoteApprove', proposal: branch.bundle.transferKind }, { gas: GAS });
  const final = await finalStatus(branch.worker, tx, branch.proposer.accountId);
  return txSummary(tx, final);
}
async function update(branch, wasm) {
  const tx = await branch.root.callRaw(branch.dao, 'update', wasm, { gas: GAS });
  const final = await finalStatus(branch.worker, tx, branch.root.accountId);
  return txSummary(tx, final);
}

async function runBaseline(bundle) {
  console.error('stage: baseline');
  const b = await importBundle(bundle);
  try {
    const before = await snapshot(b);
    const first = await approve(b);
    const afterFirst = await snapshot(b);
    const retry = await approve(b);
    const afterRetry = await snapshot(b);
    const checks = {
      initialState: b.imported.stateHash,
      initialFacts: b.factsHash,
      operationSucceeded: first.succeeded === true && first.failed === false,
      payoutExactlyBond: BigInt(afterFirst.recipientBalance) - BigInt(before.recipientBalance) === BigInt(BOND),
      retryFailed: retry.failed === true,
      retryDidNotPay: afterRetry.recipientBalance === afterFirst.recipientBalance,
      stateChanged: afterFirst.stateHash !== before.stateHash,
    };
    return { status: checks.operationSucceeded && checks.payoutExactlyBond && checks.retryFailed && checks.retryDidNotPay ? 'preserved' : 'inconclusive', initial: b.imported, localBlock: b.localBlock, before, first, afterFirst, retry, afterRetry, checks };
  } finally { await close(b); }
}
async function runCandidate(bundle) {
  console.error('stage: candidate');
  const b = await importBundle(bundle);
  try {
    const before = await snapshot(b);
    const upgrade = await update(b, fs.readFileSync(CANDIDATE));
    const afterUpgrade = await snapshot(b);
    const first = await approve(b);
    const afterFirst = await snapshot(b);
    const retry = await approve(b);
    const afterRetry = await snapshot(b);
    const checks = {
      initialState: b.imported.stateHash,
      initialFacts: b.factsHash,
      upgradeSucceeded: upgrade.succeeded === true && upgrade.failed === false,
      candidateCode: afterUpgrade.codeHash === hashContract(fs.readFileSync(CANDIDATE)),
      operationSucceeded: first.succeeded === true && first.failed === false,
      payoutExactlyBond: BigInt(afterFirst.recipientBalance) - BigInt(before.recipientBalance) === BigInt(BOND),
      retryFailed: retry.failed === true,
      retryDidNotPay: afterRetry.recipientBalance === afterFirst.recipientBalance,
    };
    return { status: checks.upgradeSucceeded && checks.candidateCode && checks.operationSucceeded && checks.payoutExactlyBond && checks.retryFailed && checks.retryDidNotPay ? 'preserved' : 'inconclusive', initial: b.imported, localBlock: b.localBlock, before, upgrade, afterUpgrade, first, afterFirst, retry, afterRetry, checks };
  } finally { await close(b); }
}
async function runCorrected(bundle) {
  console.error('stage: corrected-direct');
  const b = await importBundle(bundle);
  try {
    const before = await snapshot(b);
    const upgrade = await update(b, fs.readFileSync(CANDIDATE));
    const afterUpgrade = await snapshot(b);
    const first = await approve(b);
    const afterFirst = await snapshot(b);
    const retry = await approve(b);
    const afterRetry = await snapshot(b);
    const checks = {
      initialState: b.imported.stateHash,
      initialFacts: b.factsHash,
      upgradeSucceeded: upgrade.succeeded === true && upgrade.failed === false,
      correctedCode: afterUpgrade.codeHash === hashContract(fs.readFileSync(CANDIDATE)),
      operationSucceeded: first.succeeded === true && first.failed === false,
      payoutExactlyBond: BigInt(afterFirst.recipientBalance) - BigInt(before.recipientBalance) === BigInt(BOND),
      retryFailed: retry.failed === true,
      retryDidNotPay: afterRetry.recipientBalance === afterFirst.recipientBalance,
    };
    return { status: checks.upgradeSucceeded && checks.correctedCode && checks.operationSucceeded && checks.payoutExactlyBond && checks.retryFailed && checks.retryDidNotPay ? 'preserved' : 'inconclusive', initial: b.imported, localBlock: b.localBlock, before, upgrade, afterUpgrade, first, afterFirst, retry, afterRetry, checks };
  } finally { await close(b); }
}
async function runRecoveryExperiment(bundle) {
  console.error('stage: recovery experiment');
  const b = await importBundle(bundle);
  try {
    const before = await snapshot(b);
    const badUpgrade = await update(b, fs.readFileSync(BAD));
    const afterBadUpgrade = await snapshot(b);
    const badOperation = await approve(b);
    const afterBadOperation = await snapshot(b);
    const correctedUpgrade = await update(b, fs.readFileSync(CANDIDATE));
    const afterCorrectedUpgrade = await snapshot(b);
    const correctedOperation = await approve(b);
    const afterCorrectedOperation = await snapshot(b);
    const correctedRetry = await approve(b);
    const afterCorrectedRetry = await snapshot(b);
    const checks = {
      initialState: b.imported.stateHash,
      initialFacts: b.factsHash,
      seededBadUpgradeSucceeded: badUpgrade.succeeded === true && badUpgrade.failed === false,
      seededBadCode: afterBadUpgrade.codeHash === hashContract(fs.readFileSync(BAD)),
      seededBadOperationFailed: badOperation.failed === true,
      seededBadDidNotPay: afterBadOperation.recipientBalance === before.recipientBalance,
      correctionSucceeded: correctedUpgrade.succeeded === true && correctedUpgrade.failed === false,
      correctedOperationSucceeded: correctedOperation.succeeded === true && correctedOperation.failed === false,
      correctedPayoutExactlyBond: BigInt(afterCorrectedOperation.recipientBalance) - BigInt(before.recipientBalance) === BigInt(BOND),
      correctedRetryFailed: correctedRetry.failed === true,
      correctedRetryDidNotPay: afterCorrectedRetry.recipientBalance === afterCorrectedOperation.recipientBalance,
    };
    return { status: checks.seededBadUpgradeSucceeded && checks.seededBadCode && checks.seededBadOperationFailed && checks.seededBadDidNotPay && checks.correctionSucceeded && checks.correctedOperationSucceeded && checks.correctedPayoutExactlyBond && checks.correctedRetryFailed && checks.correctedRetryDidNotPay ? 'improved' : 'inconclusive', initial: b.imported, localBlock: b.localBlock, before, badUpgrade, afterBadUpgrade, badOperation, afterBadOperation, correctedUpgrade, afterCorrectedUpgrade, correctedOperation, afterCorrectedOperation, correctedRetry, afterCorrectedRetry, checks };
  } finally { await close(b); }
}

(async () => {
  const baseBytes = fs.readFileSync(BASE), candidateBytes = fs.readFileSync(CANDIDATE), badBytes = fs.readFileSync(BAD);
  const bundle = process.env.USE_FROZEN === '1' && fs.existsSync(path.join(OUT, 'local-frozen-bundle.json'))
    ? JSON.parse(fs.readFileSync(path.join(OUT, 'local-frozen-bundle.json'), 'utf8'))
    : await createTemplate();
  const result = {
    schema: 'near-rehearsal/local-sputnik-three-branch/v3',
    fixture: 'single frozen local configured-factory Sputnik inherited state; imported separately for each branch',
    artifacts: { base: { sha256: sha256(baseBytes), hash: hashContract(baseBytes) }, candidate: { sha256: sha256(candidateBytes), hash: hashContract(candidateBytes) }, seededBad: { sha256: sha256(badBytes), hash: hashContract(badBytes), label: 'SEEDED bad candidate: act_proposal replaced with unreachable; migration remains real candidate migration' } },
    frozenBundle: { stateHash: bundle.stateHash, codeHash: bundle.codeHash, contractBalance: bundle.contractAccount.amount, actorBalance: bundle.actorAccount.amount, recipientBalance: bundle.recipientAmount, identities: bundle.identities, context: bundle.context },
    branches: {},
  };
  result.branches.baseline = await runBaseline(bundle);
  await sleep(1000);
  result.branches.candidate = await runCandidate(bundle);
  await sleep(1000);
  result.branches.corrected = await runCorrected(bundle);
  await sleep(1000);
  result.branches.recoveryExperiment = await runRecoveryExperiment(bundle);
  const initialHashes = Object.values(result.branches).map((b) => b.checks.initialState);
  const initialFacts = Object.values(result.branches).map((b) => b.checks.initialFacts);
  result.sameStartingState = new Set(initialHashes).size === 1 && new Set(initialFacts).size === 1;
  result.primaryComparison = {
    from: 'frozen old state',
    baseline: result.branches.baseline.status,
    corrected: result.branches.corrected.status,
    sameStartingState: result.sameStartingState,
  };
  result.comparison = {
    baseline: result.branches.baseline.status,
    candidate: result.branches.candidate.status,
    corrected: result.branches.corrected.status,
    recoveryExperiment: result.branches.recoveryExperiment.status,
    sameStartingState: result.sameStartingState,
  };
  fs.writeFileSync(path.join(OUT, 'local-three-branch.json'), json(result) + '\n');
  console.log(json({ comparison: result.comparison, frozenBundle: result.frozenBundle, artifacts: result.artifacts, checks: Object.fromEntries(Object.entries(result.branches).map(([k, v]) => [k, v.checks])) }));
  if (Object.values(result.comparison).some((v) => v === 'inconclusive') || !result.sameStartingState) process.exitCode = 1;
})().catch((e) => { console.error(e.stack || e); process.exitCode = 1; });
